import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class OnlineStockSpanTest {

    @Test
    public void next[Int]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int result1 = s.next(100);
        assertEquals(1, result1);

        int result2 = s.next(-60);
        assertEquals(1, result2);

        int result3 = s.next(120);
        assertEquals(2, result3);
    }

    @Test
    public void next[Diverging]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int result1 = s.next(100);
        int result2 = s.next(-60);
        assertEquals(result1 + 1, s.next(120));
    }

    @Test
    public void next[Falling]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int result1 = s.next(100);
        int result2 = s.next(-60);
        int result3 = s.next(-55);
        assertEquals(result1 + 1, s.next(120));
        assertEquals(result2 + 1, s.next(-40));
    }

    @Test
    public void calculateSpans[Int]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int[] result = s.calculateSpans(new int[]{100});
        assertEquals(new int[]{1}, result);

        int[] result2 = s.calculateSpans(new int[]{-60});
        assertEquals(new int[]{1}, result2);

        int[] result3 = s.calculateSpans(new int[]{120, -40});
        assertEquals(new int[]{2, 1}, result3);
    }

    @Test
    public void calculateSpans[Diverging]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int[] result = s.calculateSpans(new int[]{100, 80});
        assertEquals(new int[]{2, 1}, result);

        int[] result2 = s.calculateSpans(new int[]{-60, -40});
        assertEquals(new int[]{1, 1}, result2);
    }

    @Test
    public void calculateSpans[Falling]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int[] result = s.calculateSpans(new int[]{100, -60});
        assertEquals(new int[]{2, 1}, result);

        int[] result2 = s.calculateSpans(new int[]{120, -40});
        assertEquals(new int[]{2, 1}, result2);
    }

    @Test
    public void calculateSpans[Longest]Test() {
        OnlineStockSpan s = new OnlineStockSpan();
        int[] result = s.calculateSpans(new int[]{100, 80, 60});
        assertEquals(new int[]{2, 1, 1}, result);

        int[] result2 = s.calculateSpans(new int[]{-60, -40, -20});
        assertEquals(new int[]{1, 1, 1}, result2);
    }
}
